import{describe,it,expect}from"vitest";import{readFileSync}from"node:fs";import{resolve,dirname}from"node:path";import{fileURLToPath}from"node:url";const __dirname=dirname(fileURLToPath(import.meta.url));function readExplorerFile(e){return readFileSync(resolve(__dirname,"../../frontend/major-dhyan-chand-khel-ratna-explorer",e),"utf-8")}function readLandingPage(){return readFileSync(resolve(__dirname,"../../frontend/awards-of-india-explorer/index.html"),"utf-8")}describe("Major Dhyan Chand Khel Ratna Explorer — Page Structure",()=>{let e;beforeAll(()=>{e=readExplorerFile("index.html")}),it("contains a hero section with page title and kicker",()=>{expect(e).toContain('class="khelratna-hero"'),expect(e).toContain("<h1>"),expect(e).toContain("Major Dhyan Chand"),expect(e).toContain("Khel Ratna"),expect(e).toContain("India's Highest Sporting Honour")}),it("contains all required content sections from the issue",()=>{["history","renaming","eligibility","selection","categories","medal","awardees","facts","gallery"].forEach(t=>{expect(e).toContain(`id="${t}"`),expect(e).toContain(`data-tab="${t}"`)})}),it("contains the key historical details (inception, renaming, cash prize)",()=>{expect(e).toContain("1991–92"),expect(e).toContain("Rajiv Gandhi Khel Ratna"),expect(e).toContain("6 August 2021"),expect(e).toContain("₹25 lakh"),expect(e).toContain("Viswanathan Anand")}),it("has a semantic heading hierarchy (single h1, section h2s)",()=>{const t=(e.match(/<h1[\s>]/g)||[]).length,a=(e.match(/<h2[\s>]/g)||[]).length;expect(t).toBe(1),expect(a).toBeGreaterThanOrEqual(9)}),it("uses HTTPS image sources with alt attributes",()=>{const t=e.match(/<img [^>]*>/g)||[];expect(t.length).toBeGreaterThanOrEqual(8),t.forEach(e=>{expect(e).toMatch(/src="https:\/\//),expect(e).toMatch(/alt="/),expect(e).not.toMatch(/src="http:\/\//)})}),it("links the shared stylesheet, page stylesheet, and script",()=>{expect(e).toContain('href="../../styles.css"'),expect(e).toContain('href="style.css"'),expect(e).toContain('src="script.js"')})}),describe("Major Dhyan Chand Khel Ratna Explorer — Assets",()=>{it("includes a non-empty stylesheet",()=>{const e=readExplorerFile("style.css");expect(e.length).toBeGreaterThan(1e3)}),it("includes a valid interactive script with required functions",()=>{const e=readExplorerFile("script.js");expect(e).toContain("initTabNavigation"),expect(e).toContain("activateTab"),expect(e).toContain("initCountUp"),expect(e).toContain("initTyping"),expect(e).toContain("document.addEventListener('DOMContentLoaded'")})}),describe("Major Dhyan Chand Khel Ratna — Landing Page Integration",()=>{it("is listed as a card on the Awards of India Explorer landing page",()=>{const e=readLandingPage();expect(e).toContain("Major Dhyan Chand Khel Ratna"),expect(e).toContain("../major-dhyan-chand-khel-ratna-explorer/index.html")}),it("matches the existing award card pattern (icon, category, stats, button)",()=>{const e=readLandingPage(),t=e.indexOf("Khel Ratna Card");expect(t).toBeGreaterThan(-1);const a=e.slice(t,t+1200);expect(a).toContain("award-icon"),expect(a).toContain("award-category"),expect(a).toContain("award-year"),expect(a).toContain("award-btn"),expect(a).toContain('class="award-card glass-card"')})});